import java.io.*;import java.nio.file.*;import java.util.*;
public class Main {record Pass(String id,String reg,String name,int route,String stop,String date,int amount){}static String csv(String s){return "\""+s.replace("\"","\"\"")+"\"";}public static void main(String[]a)throws Exception{Path p=Path.of("passes.csv");Pass x=new Pass("P1001","192311001","Kumar, Jr",12,"Tambaram","2027-03-31",450000);try(BufferedWriter w=Files.newBufferedWriter(p)){w.write(x.id()+","+x.reg()+","+csv(x.name())+","+x.route()+","+csv(x.stop())+","+x.date()+","+x.amount());}System.out.println(Files.readString(p));}}
